&lt;a href=&quot;/Wiki/Pathfinder-RPG.Aventures occultes (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Occult Adventures/Aventures occultes&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoOA.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;b&gt; &#201;cole &lt;/b&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Pr&#233;sentation-Des-Sorts#Abjuration.html&quot; title=&quot;Abjuration&quot;&gt;Abjuration&lt;/a&gt; ; &lt;b&gt;Niveau&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Psychiste.html&quot; title=&quot;Le psychiste&quot;&gt;Psy&lt;/a&gt; 5  
&lt;b&gt;Temps d’incantation&lt;/b&gt; 1 &lt;a class=&quot;pagelink&quot; href=&quot;Types-Dactions#Immediate.html&quot; title=&quot;Action imm&#233;diate&quot;&gt;action imm&#233;diate&lt;/a&gt;  
&lt;b&gt;Composantes&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Pr&#233;sentation-Des-Sorts#Composantes.html&quot; title=&quot;composantes&quot;&gt;V&lt;/a&gt;  
&lt;b&gt;Port&#233;e&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Pr&#233;sentation-Des-Sorts#La_Port&#233;e_18.html&quot; title=&quot;courte&quot;&gt;personnelle&lt;/a&gt;  
&lt;b&gt;Cible&lt;/b&gt; lanceur de sorts  
&lt;b&gt;Dur&#233;e&lt;/b&gt; 1 &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Round.html&quot; title=&quot;round&quot;&gt;round&lt;/a&gt;
&lt;hr&gt;
Ce sort fonctionne comme &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Bouclier-Des-Pens&#233;es-Iii.html&quot; title=&quot;Bouclier des pens&#233;es III&quot;&gt;bouclier des pens&#233;es III&lt;/a&gt;&lt;/i&gt; mais une cr&#233;ature qui tente de lire les pens&#233;es du personnage alors qu’il est sous l’effet de ce sort doit r&#233;ussir un jet de &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdesauvegarde.html&quot; title=&quot;Volont&#233;&quot;&gt;Volont&#233;&lt;/a&gt; ou &#234;tre &lt;a class=&quot;pagelink&quot; href=&quot;&#201;tats-Pr&#233;judiciables.html#&#201;tourdi&quot; title=&quot;Les &#233;tats pr&#233;judiciables&quot;&gt;&#233;tourdie&lt;/a&gt; pendant 1d4 rounds. De plus, si le personnage r&#233;ussit son jet de sauvegarde contre un &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Broyage-Psychique-I.html&quot; title=&quot;Broyage psychique I&quot;&gt;broyage psychique&lt;/a&gt;&lt;/i&gt;, il ne subit aucun d&#233;g&#226;t. On peut lancer ce sort sous sa version r&#233;duite.&lt;br /&gt;&lt;br /&gt;&lt;br /&gt;&lt;br /&gt;&lt;div class=&quot;box&quot;&gt;
&lt;h1 class=&quot;separator&quot;&gt;Bouclier des pens&#233;es III&lt;a class=&quot;headeranchor&quot; id=&quot;Bouclier_des_pens&#233;es_III_0&quot; href=&quot;#Bouclier_des_pens&#233;es_III_0&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h1&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.Aventures occultes (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Occult Adventures/Aventures occultes&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoOA.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;b&gt; &#201;cole &lt;/b&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Pr&#233;sentation-Des-Sorts#Abjuration.html&quot; title=&quot;Abjuration&quot;&gt;abjuration&lt;/a&gt; ; &lt;b&gt;Niveau&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Psychiste.html&quot; title=&quot;Le psychiste&quot;&gt;Psy&lt;/a&gt; 4  
&lt;b&gt;Temps d’incantation&lt;/b&gt; 1 &lt;a class=&quot;pagelink&quot; href=&quot;Types-Dactions#Immediate.html&quot; title=&quot;Action imm&#233;diate&quot;&gt;action imm&#233;diate&lt;/a&gt;  
&lt;b&gt;Composantes&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Pr&#233;sentation-Des-Sorts#Composantes.html&quot; title=&quot;composantes&quot;&gt;V&lt;/a&gt;  
&lt;b&gt;Port&#233;e&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Pr&#233;sentation-Des-Sorts#La_Port&#233;e_18.html&quot; title=&quot;courte&quot;&gt;personnelle&lt;/a&gt;  
&lt;b&gt;Cible&lt;/b&gt; lanceur de sorts  
&lt;b&gt;Dur&#233;e&lt;/b&gt; 1 &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Round.html&quot; title=&quot;round&quot;&gt;round&lt;/a&gt;
&lt;hr&gt;
Ce sort fonctionne comme &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Bouclier-Des-Pens&#233;es-I.html&quot; title=&quot;Bouclier des pens&#233;es I&quot;&gt;bouclier des pens&#233;es I&lt;/a&gt;&lt;/i&gt; mais le bonus de circonstances aux jets de &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdesauvegarde.html&quot; title=&quot;Volont&#233;&quot;&gt;Volont&#233;&lt;/a&gt; pour r&#233;sister aux effets mentaux passe &#224; +8. De plus, une cr&#233;ature qui tente de lire les pens&#233;es du personnage alors qu’il est sous l’effet de ce sort doit r&#233;ussir un jet de &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdesauvegarde.html&quot; title=&quot;Volont&#233;&quot;&gt;Volont&#233;&lt;/a&gt; ou &#234;tre &lt;a class=&quot;pagelink&quot; href=&quot;&#201;tats-Pr&#233;judiciables.html#&#201;tourdi&quot; title=&quot;Les &#233;tats pr&#233;judiciables&quot;&gt;&#233;tourdie&lt;/a&gt; pendant 1 round. On peut lancer ce sort sous sa version r&#233;duite.&lt;br /&gt;&lt;br /&gt;&lt;br /&gt;&lt;br /&gt;&lt;div class=&quot;box&quot;&gt;
&lt;h1 class=&quot;separator&quot;&gt;Bouclier des pens&#233;es I&lt;a class=&quot;headeranchor&quot; id=&quot;Bouclier_des_pens&#233;es_I_1&quot; href=&quot;#Bouclier_des_pens&#233;es_I_1&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h1&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.Aventures occultes (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Occult Adventures/Aventures occultes&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoOA.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;b&gt; &#201;cole &lt;/b&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Pr&#233;sentation-Des-Sorts#Abjuration.html&quot; title=&quot;Abjuration&quot;&gt;Abjuration&lt;/a&gt; ; &lt;b&gt;Niveau&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Psychiste.html&quot; title=&quot;Le psychiste&quot;&gt;Psy&lt;/a&gt; 2  
&lt;b&gt;Temps d’incantation&lt;/b&gt; 1 &lt;a class=&quot;pagelink&quot; href=&quot;Types-Dactions#Immediate.html&quot; title=&quot;Action imm&#233;diate&quot;&gt;action imm&#233;diate&lt;/a&gt;  
&lt;b&gt;Composantes&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Pr&#233;sentation-Des-Sorts#Composantes.html&quot; title=&quot;composantes&quot;&gt;V&lt;/a&gt;  
&lt;b&gt;Port&#233;e&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Pr&#233;sentation-Des-Sorts#La_Port&#233;e_18.html&quot; title=&quot;courte&quot;&gt;personnelle&lt;/a&gt;  
&lt;b&gt;Cible&lt;/b&gt; lanceur de sorts  
&lt;b&gt;Dur&#233;e&lt;/b&gt; 1 &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Round.html&quot; title=&quot;round&quot;&gt;round&lt;/a&gt;
&lt;hr&gt;
D&#232;s que le personnage sent une intrusion, il dresse une d&#233;fense pour prot&#233;ger son esprit contre les attaques ou les analyses. Cela se traduit par un bonus de circonstances de +4 aux jets de &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdesauvegarde.html&quot; title=&quot;Volont&#233;&quot;&gt;Volont&#233;&lt;/a&gt; contre les effets mentaux. Tant que le sort fait effet, les sorts et effets permettant &#224; une cr&#233;ature de lire dans l’esprit du personnage ne lui fournissent aucune information.
&lt;/div&gt;&lt;/div&gt;&lt;br /&gt;&lt;div class=&quot;box&quot;&gt;&lt;style&gt;.box { width: 844px; } #PageContentDiv .voiraussi h4 { line-height: 16px; }&lt;/style&gt;&lt;div class=&quot;voiraussi&quot; style=&quot;width:100%&quot;&gt;
&lt;h4 class=&quot;separator&quot;&gt;Sorts qui &#171; fonctionnent comme &#187; &lt;i&gt;bouclier des pens&#233;es IV&lt;/i&gt;&lt;a class=&quot;headeranchor&quot; id=&quot;Sorts_qui_&#171;_fonctionnent_comme_&#187;_bouclier_des_pens&#233;es_IV__0&quot; href=&quot;#Sorts_qui_&#171;_fonctionnent_comme_&#187;_bouclier_des_pens&#233;es_IV__0&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h4&gt;&lt;/div&gt;
&lt;h1 class=&quot;separator&quot;&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Bouclier-Des-Pens&#233;es-V.html&quot; title=&quot;Bouclier des pens&#233;es V&quot;&gt;Bouclier des pens&#233;es V&lt;/a&gt;&lt;a class=&quot;headeranchor&quot; id=&quot;_Bouclier_des_pens&#233;es_V__2&quot; href=&quot;#_Bouclier_des_pens&#233;es_V__2&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h1&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.Aventures occultes (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Occult Adventures/Aventures occultes&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoOA.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;b&gt; &#201;cole &lt;/b&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Pr&#233;sentation-Des-Sorts#Abjuration.html&quot; title=&quot;Abjuration&quot;&gt;Abjuration&lt;/a&gt; ; &lt;b&gt;Niveau&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Psychiste.html&quot; title=&quot;Le psychiste&quot;&gt;Psy&lt;/a&gt; 6  
&lt;b&gt;Temps d’incantation&lt;/b&gt; 1 &lt;a class=&quot;pagelink&quot; href=&quot;Types-Dactions#Immediate.html&quot; title=&quot;Action imm&#233;diate&quot;&gt;action imm&#233;diate&lt;/a&gt;  
&lt;b&gt;Composantes&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Pr&#233;sentation-Des-Sorts#Composantes.html&quot; title=&quot;composantes&quot;&gt;V&lt;/a&gt;  
&lt;b&gt;Port&#233;e&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Pr&#233;sentation-Des-Sorts#La_Port&#233;e_18.html&quot; title=&quot;courte&quot;&gt;personnelle&lt;/a&gt;  
&lt;b&gt;Cible&lt;/b&gt; lanceur de sorts  
&lt;b&gt;Dur&#233;e&lt;/b&gt; 1 &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Round.html&quot; title=&quot;round&quot;&gt;round&lt;/a&gt;/niveau ; voir texte  
&lt;hr&gt;
Ce sort fonctionne comme &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Bouclier-Des-Pens&#233;es-Iv.html&quot; title=&quot;Bouclier des pens&#233;es IV&quot;&gt;bouclier des pens&#233;es IV&lt;/a&gt;&lt;/i&gt; en dehors des modifications ci-dessus. Il se termine imm&#233;diatement si le personnage rate un jet de sauvegarde contre un effet mental. On peut lancer ce sort sous sa version r&#233;duite.
&lt;/div&gt;
